/** A message in a thread, sent or received by its account link. */
export interface Message {
  id: string;
  /** A thread: a conversation between one of the team's account links and one profile. */
  threadId: string;
  /** An account link: a platform account the team connected to Inboxapp, the team's side of a conversation. */
  accountLinkId: string;
  platform: Platform;
  /** Null when the platform assigned none. */
  platformId: string | null;
  /** `inbound` was received from the other side. `outbound` was sent by the account link. */
  direction: MessageDirection;
  /** Who on the team sent an outbound message. Null for inbound messages and for messages sent outside Inboxapp. */
  sentBy: MessageSentBy | null;
  /** The text as Inboxapp last saw it. A deleted message keeps its content. */
  content: string;
  entities: MessageEntities;
  /** Media, and at most one link card, told apart by `kind`. */
  attachments: Array<MessageAttachmentsItem>;
  /** Set when the message forwards another one, with the forwarded text as the sender's app declared it. Null otherwise. */
  forwarded: MessageForwarded | null;
  reactions: Array<Reaction>;
  /** When the message was last edited. Null when it hasn't been, or when the edit time wasn't recorded. Every version is in `GET /messages/{messageId}/history`. */
  editedAt: string | null;
  /** Set once the message was deleted for the account link or unsent for everyone. Deleted messages stay in lists, and `GET /messages/{messageId}/history` has the scope. */
  deletedAt: string | null;
  createdAt: string;
  platformData: MessagePlatformData;
  /** The message this one replies to. Null when it isn't a reply. */
  replyTo: MessageReplyTo | null;
  thread?: Thread;
  accountLink?: AccountLink;
}

/** `inbound` was received from the other side. `outbound` was sent by the account link. */
export type MessageDirection = "inbound" | "outbound" | (string & {});

/** Who on the team sent an outbound message. Null for inbound messages and for messages sent outside Inboxapp. */
export type MessageSentBy =
  | MessageSentByMember
  | MessageSentByAgent
  | MessageSentByCampaign
  | MessageSentByAPIToken;

/** A team member sent it from Inboxapp. */
export interface MessageSentByMember {
  type: "member";
  /** A member: a person on the team. */
  memberId: string;
  member?: Member;
}

/** An agent the member authorized sent it, such as an MCP client. It acts with the member's access. */
export interface MessageSentByAgent {
  type: "agent";
  agentId: string;
  /** A member: a person on the team. */
  memberId: string;
  agent?: MessageSentByAgentAgent;
  member?: Member;
}

export interface MessageSentByAgentAgent {
  id: string;
  name: string;
}

/** A campaign sent it. */
export interface MessageSentByCampaign {
  type: "campaign";
  campaignId: string;
  /** The sequence step that sent it, possibly since removed. Null when no step was recorded. Not expandable. */
  stepId: string | null;
}

/** An API token sent it. `tokenId` is null on messages sent before tokens were recorded, and `token` is absent once the token is deleted. */
export interface MessageSentByAPIToken {
  type: "api";
  tokenId: string | null;
  token?: MessageSentByAPITokenToken;
}

export interface MessageSentByAPITokenToken {
  id: string;
  name: string;
}

/** Parts of `content` the platform marked up. */
